prompt:
What language is this written in?

fn main() {
    let names = vec!["ada", "grace", "linus"];
    for (i, name) in names.iter().enumerate() {
        println!("{}: {}", i, name.to_uppercase());
    }
    let total: usize = names.iter().map(|n| n.len()).sum();
    println!("total length {}", total);
}
